245	// delegateRunNextActions is the ways forward of the attempt run belongs to,
246	// for a run that just stopped (R9).
247	func delegateRunNextActions(store posemodel.Store, run posemodel.ReviewRun, err error) []delegateNextAction {
248		if err != nil || run.AttemptID == "" || run.Status == posemodel.ReviewRunCompleted {
249			return nil
250		}
251		attempts, _, lerr := store.ListDelegationAttempts()
252		if lerr != nil {
253			return nil
254		}
255		for _, a := range attempts {
256			if a.AttemptID == run.AttemptID {
257				return delegateNextActions(store, a)
258			}
259		}
